script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const viewRoutes = {
        experience: 'experience',
        pc: 'pc',
        components: 'components'
    };
    const params = {
        parentScreenId: event.payload.parentScreenId,
        parentElementId: event.payload.parentElementId
    };
    const route = viewRoutes[api.context.props.mode];
    const fieldName = route === 'experience' ? 'experienceId' : (route === 'components' ? 'macroponentId' : 'extensionpointId');
    const fieldValue = (route === 'components' && params.parentElementId) ? event.payload.parentMacroponentId : api.context.props.experienceId;
    return {
        route,
        fields: {
            [fieldName]: fieldValue
        },
        params,
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: null,
        targetRoute: null,
        external: null
    };
}

function evaluateEvent({api, event}) {
	const mappedPayload = {
		route: null,
		fields: null,
		params: null,
		redirect: null,
		passiveNavigation: null,
		title: null,
		multiInstField: null,
		targetRoute: null,
		external: null,
		...event.payload
	};

	return mappedPayload;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    return api.elements.builder_core.selectedCompositionElement.definition.type === "REPEATER" ||
        api.elements.builder_core.selectedComponentDefinition.dispatchedEvents.length === 0;
}

